window.SEARCH_INDEX=[{"u": "login-screen.html", "t": "Login Screen", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › Login Screen", "x": "Enter User Name: First initial last name (no spaces) Enter Password: Created by user (case sensitive) Select Location from list of available locations that you want to log into"}, {"u": "home-page.html#logout", "t": "Logout", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › Home Page", "x": "Shows User logged in along with location logged in to. Locations can be changed as easily as clicking location with your cursor and selecting from the list of available locations. If logging into multiple locations on a regular basis, periodically verify the location logged into."}, {"u": "home-page.html#start-a-task", "t": "Start a Task", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › Home Page", "x": "Can be done one of two ways. This is a personal preference, both take you to the same place. By hovering over selected module in tool bar shown below Selecting module on left hand side of home screen and then selecting from Start a Task list"}, {"u": "home-page.html#tools", "t": "Tools", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › Home Page", "x": "Allows additional options by user based on access rights Options – Allows the option of previewing or sending directly to printer based on report type along with the number of copies to print by default. Also allows for sales order, invoicing and inventory search keystroke setup. Configure Search Results – Allows the option to customize by user search results screens based on search type. User Defined Import – Allows user defined field values to be imported based on access rights. Customer Price Lists – Allows customer price lists to be generated based on customer price level and any additional customer price rules. Integration Manager – Allows reintegration of documents to financial software based on access rights."}, {"u": "home-page.html#help", "t": "Help", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › Home Page", "x": "Displays software version installed (i.e. 14.3.1.5). First number designates year, second designates Quarter."}, {"u": "home-page.html#find", "t": "Find", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › Home Page", "x": "Gives access to all current and historical data based on data type (Quotes, Sales Orders, Transfers, Customers, Customer Deposits, Invoices, Inventory……) Lists documents/customers by most current. Data that displays is determined by the configuration of sales order search results. Displays first several hundred records. Beyond that Search will need to be used. By default, search results will display only data from the location you are logged into. Use “Show Advanced Search” to display individually specified or all wholesale locations."}, {"u": "home-page.html#reports", "t": "Reports", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › Home Page", "x": "Gives visibility to a wide range of reports defined by report category and selection of report. Ability to display, print, and export reports based on criteria selection available in each report."}, {"u": "home-page.html#today-s-reminders", "t": "Today’s Reminders", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › Home Page", "x": "Displays all open sales orders for user logged in and gives the ability to open order directly from home screen."}, {"u": "configure-search-results.html", "t": "Configure Search Results", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › Configure Search Results", "x": "Ability to configure all search results screen based on user preference. From Application Tool Bar, Select Configure Search Results Select Search Type from Drop Down When configuring sales order search screen select Inventory Search (Orders and Invoices) from drop down Review current visible fields and add/delete using arrow keys between field boxes Once desired visible fields are selected, sort in desired column order with arrow keys to right of Visible Fields box Repeat for additional search types if desired Select Save and Close when complete"}, {"u": "customer-pricing-report.html", "t": "Customer Pricing Report", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › Customer Pricing Report", "x": "Ability to create pricing reports on a customer by customer basis and include specific information. From Application Tool Bar, Select Customer Pricing Report Select Report Template from Drop Down Select Add Customers with Add icon Enter known search criteria Select search Highlight selection and select OK Select Sub Manufacturer tab and select desired Sub Manufacturers or Select All To include winter tires, check box Select Product Class Tab and select desired Classes or Select All Select Run Report Report will display for printing or exporting to Excel"}, {"u": "user-options.html", "t": "User Options", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › User Options", "x": "Ability to define and modify optional information by user. Select Tools from Application Tool Bar and then Options."}, {"u": "user-options.html#reports-tab", "t": "Reports Tab", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › User Options", "x": "Allows User to setup print settings specifically related to their user credentials Select Desired Report Type Toggle Preview or Send Directly to printer Select printer icon and select desired default printer Set desired print quantity Select OK"}, {"u": "user-options.html#sales-order-tab", "t": "Sales Order Tab", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › User Options", "x": "Allows user to set specific settings based on user credentials. Default Settings most commonly used Automatically show customer’s open order Maximize order form Cursor Starting Position – Customer Name Also desired is account number if user has memorized account numbers Item ID – Manufacturer Sku"}, {"u": "user-options.html#invoice-entry-tab", "t": "Invoice Entry Tab", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › User Options", "x": "Allows user to set specific settings based on user credentials. Default Settings most commonly used Automatically print invoice when process This is at NEW INVOICE and will be based on setting in print setup whether goes directly to printer or displays a print preview at time of selecting process Cursor starting position – Customer Name Also desired is account number if user has memorized account numbers Item ID – Manufacturer Sku"}, {"u": "user-options.html#inventory-search-tab", "t": "Inventory Search Tab", "p": "SECTION 1: LOGIN SCREEN & HOME PAGE › User Options", "x": "Allows user to set specific settings based on user credentials. Default Settings most commonly used Use ESC to clear inventory search Warn if no customer has been added to the order when searching inventory Reset inventory search after adding an item to the basket Set this based on the documents you will be using and the desire to go back to the global search box after every add. This is very helpful when creating a manual PO, inventory receipt or inventory adjustment. Use plus key as tab Dual fitment separator character – DO NOT CHANGE FROM ‘/’ Inventory generally loaded prior to go live using ‘/’"}, {"u": "sales-orders.html", "t": "Sales Orders", "p": "SECTION 2:  SALES › Sales Orders", "x": "Verify and/or change location prior to starting a new order. To change location, select location with one click and choose desired location for list. Home Screen: Select then select from start a task"}, {"u": "sales-orders.html#toolbar", "t": "Toolbar", "p": "SECTION 2:  SALES › Sales Orders", "x": "Save and Close – Saves order and closes order Save and New – Saves order and takes you directly to new order screen Save as Quote – Saves order as quote Process – Processes order depending on delivery method selected in order Cancel Order – Cancels an order in the open status Prints Orders Allows direct credit card payment Audit History – Displays all editing done to order (including price changes, deleted items, added items, etc.) Copy Order – Allows order to be copied to new order Shortcut keys – Allows configuration and save of shortcut keys"}, {"u": "sales-orders.html#creating-order", "t": "Creating Order", "p": "SECTION 2:  SALES › Sales Orders", "x": "Enter customer name or customer ID Displays only customer related to that home location If customer has existing orders, will prompt to select an existing order or cancel to start new order. An order in processing status should not be selected and added to. Processing status means that order has been sent to shipment manager. SUGGEST: adding to open sales orders to minimize number of invoices customer receives. Allows emailing directly from sales order Allows viewing of customer record from sales order (including customer pricing) Allows customer to be changed. Will update customer pricing when changed. Verify header information (Populates from customer record data) Billing Address : Will generally be the same as shipping information Delivery Method : Route, Will-Call, UPS, FedEx, LTL and Direct Ship Change if needed based on customer preference for order Shipping Address : Defaults based on customer record setup May be multiple ship to locations – will notify in yellow Requested Ship Date : Date will default to today’s date unless changed Change this if customer wants to order but not take delivery until a date in the future If date change required, MUST use date product will be loaded NOT day tires need to be delivered Estimated Route : Will display the next available route customer will be delivered Can be on multiple routes Ship Complete : Check only if you want to ship order after all backordered items have been filled PO Number : May be set as a required field based on customer record setup If required, flashing red exclamation point will appear until field has been populated Price Level : Default price level based on shipping address in customer record setup This field cannot be changed Salesperson Name : Defaults to ASR assigned to customer in customer record setup Payment Terms : Defaults to terms set in customer record setup Tax Rate : Defaults to tax rate set in customer record setup Discount Percent : Used to take a discount on the entire order Special Programs : Select special program (see Goodyear processing procedures) Select Add Items Optional checkbox for Available items only Optional Checkbox for Discontinued items only Discontinued items are set in item master record and display in red Global Lookup: Enter search criteria Universal Sku: simple tire size, three-digit mfg. abbreviation, and mfg. item number (i.e. 2056515GOO402406477) Searchable by all or any combination of universal Sku Description Filter: Used to narrow search results based on description i.e. line of tire, speed rating, etc.) When description filter is removed goes back to original search results User Sku Code Lookup: Another lookup based on what is populated in User SKU field in item record Optional checkbox to display winter tires only Use Inventory Tree Lookups: Can be used to search by inventory tree nodes Select items to add to order Search results display by largest quantity available Search results display the customer’s price based on default price level set in customer record and any additional customer pricing rules added for them specifically Enter quantity of desired item and enter. Will move selected item to cart below search screen and return to Global Lookup for next item search Note: ALL search columns are sortable by clicking column header to sort in ascending order. Click again will go back to descending order. Select when all items have been added Items will be populated in sales order Tire tax will automatically be added based on type of tire and Tire Tax designation in customer record Items will display with backordered quantities if none available Backorders are filled based on ordered date Enter additional line items if necessary Add comments if desired Select Select desired comment Select Done GP Display: Displays gross profit percent and dollars If customer is over credit limit this will display amount over credit limit Depending on company setup this order may not be delivered until resolved Verify order has green check mark in Process Based on delivery method follow below process ROUTE: Save and Close order. Order processing will be handled by warehouse personnel WILL-CALL: Process and print invoice to picking warehouse printer FED-EX: Process and print invoice to picking warehouse printer UPS: Process and print invoice to picking warehouse printer LTL: Print work order to warehouse for manual picking DIRECT SHIP: Process and print/email to custom"}, {"u": "sales-orders.html#customer-details-tab", "t": "Customer Details Tab", "p": "SECTION 2:  SALES › Sales Orders", "x": "Displays available credit, credit limit and customer comments Provides ability to lookup item history Global Lookup: Enter ALL or a combination of Universal Sku Description Filter: Enter additional filter information (from item description) Select start and end date from calendar dropdown Enter Vehicle unit ID in desired Select Return to General Tab when complete"}, {"u": "sales-orders.html#financials-tab", "t": "Financials Tab", "p": "SECTION 2:  SALES › Sales Orders", "x": "Displays Balance Due and Payment information Displays Open Receivables Displays All Transactions Note: Can be used to copy into Excel to provide to customer based on access rights."}, {"u": "sales-orders.html#backorders", "t": "Backorders", "p": "SECTION 2:  SALES › Sales Orders", "x": "Displays all backorders for customer"}, {"u": "sales-orders.html#special-programs", "t": "Special Programs", "p": "SECTION 2:  SALES › Sales Orders", "x": "Used for validating National Account, P&R, Secondary Supply and Government submission (See individual procedures) Default Cash Customer – Displays ONLY when default cash customer has been selected on sales order. Provides fields to enter ship-to information. Printable on invoices and reportable. Note: Quotes will be done through new Order. When order generation is complete choose SAVE AS QUOTE. By using this function, inventory will not be allocated, and sales orders will display in the (Quote) status. Quotes can be retrieved by selecting Quotes from Find window on home screen."}, {"u": "special-programs.html", "t": "Special Programs", "p": "SECTION 2:  SALES › Special Programs", "x": "Gives the ability to assign an order and/or customer to a special program. Special programs can be created for National accounts, manufacturer volume bonus programs or internal volume bonus incentives. This functionality gives flexibility to assign a billing account (in-house AR account), set tax exemptions, and potentially send directly to manufacturer at invoice. Home Screen: Select then select “Special Programs” from start a task"}, {"u": "special-programs.html#main-tab", "t": "Main Tab", "p": "SECTION 2:  SALES › Special Programs", "x": "Select Add New Program Enter desired Group Name and prefix Verify active status (by default active checkbox will be checked) Selecte Program Type Manufacturer National Account - National Accounts, Secondary Supply, Car Dealers, and Government programs Manufactuer Volume Bonus - Bonus programs funded by the manufactuer (i.e. Yokohama Advantage, Kumho Fuel, etc….). This could also be used for In-House funded volume bonus programs as well such as customer specific volume bonus programs Assign Begins date if needed Assign Expires date if needed Assign Billing Account Number with elipsis – Used for National accounts when billing to a intercompany AR account Select appropriate is open status Select desired “Is Open” status Unchecked – Limits on those customers defined in program to be selected Checked – allows any customer to be added through sales order If checked, Select Add Customer Search for desired customer via customer ID, Customer Name or Customer Phone Highlight desired customer and select OK or double click customer Note *:* If customer has multiple ship-to’s and you want to include make sure you select all. Select Save Changes"}, {"u": "special-programs.html#program-attributes-tab", "t": "Program Attributes Tab", "p": "SECTION 2:  SALES › Special Programs", "x": "Allows attributes to get set by program. Select Add Attribute Will automatically bring the next attribute to bottom of list Can use Dropdown to select desired attribute Program Price Level – Allows price level to be assigned to Special Program so each time the program is selected, the price level with automatically change Tire Tax Exempt – Allows tire tax exempt status to be be set regardless of customer setting FET Exempt - Allows FET exempt status to be be set regardless of customer setting"}, {"u": "special-programs.html#program-skus-tab", "t": "Program Skus Tab", "p": "SECTION 2:  SALES › Special Programs", "x": "Ability to set desired branches or individual Skus for program. Select (Highlight) desired branch of the inventory tree Select Add Item Select Expired date if required Note *:* This can be done at any branch or single Sku of the tree (i.e. Manufacturer, Sub Mfg., Class, SubClass, Category, or individual Sku)."}, {"u": "special-programs.html#program-submission-history-tab", "t": "Program Submission History Tab", "p": "SECTION 2:  SALES › Special Programs", "x": "Displays all submissions based on criteria selected and the ability to see validation window and the opportunity to resubmit if unposted if manufacturer integration is available and being utilized. Select location from dropdown Select From and To dates Select desired posted status Yes, are those that have been transmitted to mfg. No, are those that have not been transmitted Select Search Displays results based on selections Select to see validation information Use when posted status is No Select Repost if needed Note: If using retail application, Special Programs setup in wholesale can be copied to retail application."}, {"u": "create-new-invoice.html", "t": "Create New Invoice", "p": "SECTION 2:  SALES › Create New Invoice", "x": "Designed for the purpose of billing/crediting non-inventoried items and returned goods. Home Screen: Sales Module and select New Invoice Enter customer ID or search by customer name Select Add Items or F2 Enter Sku in Global Lookup Enter qty and enter; This moves item and qty down to shopping cart Enter Item(s) until all items have been added Review and edit quantity, price and cost for accuracy Note: In this type of transaction, often cost will need to be overwritten to $0, verify costs are correct. Select add to order – This moves Sku selections to invoice Add Invoice Comments as reference if necessary Can also use line item comments if comment will change per line item. Right click anywhere in the row and select item comment and type comment Verify check box is checked if print on invoice is desired Select Save or Print If print is selected, it will automatically save when it brings up the invoice to print Note: Processing is only necessary when creating new invoice if you want to immediately push to financial software."}, {"u": "create-return.html", "t": "Create Return", "p": "SECTION 2:  SALES › Create Return", "x": "At Home Screen: Start a task and select Enter Customer ID or Customer Name and enter to populate customer information in header Select in upper right corner. Customer history will display by invoice number Highlight Invoice to reverse and select ok *Also, can reverse specific line items by opening invoice with + and select the specific line items to reverse. To select multiple items, hold CTRL key and make selections Selection(s) will populate invoice with reverse quantities along with original price billed and original cost at the time of sale. Make appropriate changes to quantities based on credit requested Copy Reference information from User Comments field (does not print) where auto populates to invoice comments that will print for customer reference. Add additional invoice comments if necessary. Print copies if needed Not required to select process prior to save or save and close. Since you are already generating an actual invoice, once save or save and close is selected this is a valid invoice. Selecting process with only send invoice to Great Plains. Note: Will not cause any harm if selected but not necessary to select."}, {"u": "filling-back-orders.html", "t": "Filling Back Orders", "p": "SECTION 2:  SALES › Filling Back Orders", "x": "Home Screen: Select then select from start a task"}, {"u": "filling-back-orders.html#setting-priorities", "t": "Setting Priorities", "p": "SECTION 2:  SALES › Filling Back Orders", "x": "By Default, orders are prioritized by order date. Oldest will fill first Set criteria selection From and To date will default – Change if needed Create Date: Date order was created will be default Requested Ship Date: Toggle on if want to deviate from default Routes: Select All will be default. Unselect and select specific rotes if needed Item ID: Searches and display backorders for that item only Customer Name: Search by customer for orders specific to them Open Orders: By default, is checked, uncheck if desired. Refers to order that can be added to. Processed orders: By default, is checked, uncheck if needed. Refers to order that are in the process of being shipped Note: allows information that is displayed to be copied and then pasted into another application such as Word or Excel. Include header text will be check by default in this function. Edit priority column to reflect the order in which you would like orders filed Select Save Priorities"}, {"u": "filling-back-orders.html#check-availability", "t": "Check Availability", "p": "SECTION 2:  SALES › Filling Back Orders", "x": "Select Displays which line items are available to be filled with green check mark"}, {"u": "filling-back-orders.html#fill-backorders", "t": "Fill Backorders", "p": "SECTION 2:  SALES › Filling Back Orders", "x": "If items have quantity available to fill it will be displayed in column labeled Qty. Avail. To Fill. May only fill partially and the difference will be reflected in Max Qty. to Fill column. By default, Select All is checked. If specific orders are desired, uncheck select all and check line items individually (May want to do this in situation where full quantity ordered cannot be filled) Select Exit Fill Backorders screen when complete"}, {"u": "filling-back-orders.html#other-buttons", "t": "Other Buttons", "p": "SECTION 2:  SALES › Filling Back Orders", "x": "Can be used to refresh screen to reflect new backordered items that have come in since initially opened. Can be used to open order"}, {"u": "customer-record-setup.html", "t": "Customer Record Setup", "p": "SECTION 2:  SALES › Customer Record Setup", "x": "Accounts Receivable customer setup is one of the top three areas that consistency, completeness, and accuracy will greatly impact workflow."}, {"u": "customer-record-setup.html#general-tab", "t": "General Tab", "p": "SECTION 2:  SALES › Customer Record Setup", "x": "Defines all general customer information. Populate as needed bases on your business practices and procedures. Customer Name: Legal name Customer ID: Auto population unless choose to override Short Name: Abbreviated searchable name Customer Class: Select from predetermined drop-down list Status: Active by default Salesperson Name: Person responsible for account Customer Since: Calculated field not editable Balance: Calculated field imported from financial software Terms: Select term approved by credit manager P.O. Required: Check only if all orders are required to have a PO Tax Group: Select appropriate tax from dropdown Taxable by default unless Exempt is chosen from dropdown Select Nome if default tax rate should be that of the servicing location Department Code: Select appropriate department code. If not used select 00 Tire Tax Exempt: Check box if tire tax exempt Tax Exemption Number: Populate if exemption box is checked. Ship Method: Select default ship method for customer from dropdown Ship Complete: Check only if the customer prefers to have entire order ship at one time Credit Limit: Enter amount approved by credit manager eCommerce Credit Factor: If applicable Unused Credit: Calculated field imported from financial software Default Price Level: Select appropriate price level from dropdown box Discount %: Enter percentage if applicable Finance Charge: Enter percentage if applicable Memo 1: Free form field – WILL print on invoice Memo 2: Free form field – WILL NOT Print on invoice (600 varchar field) Messages: Free form field – WILL NOT print on invoice Show Alert: If checked will display at creation of sales order"}, {"u": "customer-record-setup.html#addresses-tab", "t": "Addresses Tab", "p": "SECTION 2:  SALES › Customer Record Setup", "x": "Defines all address, pricing, shipping and internet ordering information by address. Address information CAN be different than general customer information. Populate as needed bases on your business practices and procedures. Address ID: Primary will auto populate in Address ID If shipping address and billing address are not the same, consider using PRIMARY and SHIPPING in route ID so they can be properly selected above. If additional shipping addresses, consider a naming convention to keep consistent. If multiple shipping addresses, consider using street name for additional If shipping to a separate customer, consider using customer name If national account, consider using customer main account number for reporting Status: Active by default Address 1: UPS approved address Address verification can be obtained on www.usps.com Suggest ALL CAPS and no punctuation Address 2: Other address information Used for PO Box or other address related data Country: Select from drop down box Zip Code: Enter zip code – city/state will auto populate Verify city matches postal service approved city Phone Number: Include extension if available Fax Number: If applicable Email Address: Full email address if applicable Website: Customer website if applicable Home Location: Designation of primary distribution center based on address Tax Group 1 and 2: Make sure they are both populated Price level: Default price level for location (Can be different than general information tab) Ignore Customer Pricing: Check if applicable Consolidate Orders on Invoice: Check if applicable FET Exempt: Check if applicable Delivery fee exempt: Check if applicable Tire Fee Exempt: Check if applicable Routes Box 1: Select ship method for address (Can be different than general information tab) If Primary is BILLING address only – select BILLING as ship method If Primary is the billing and shipping address – select designation on customer setup form Routes Box 2: If ship via is route in box above, select route again**.** Assign route unless route manager will handle route assignment Return to top of Address tab and complete, once all addresses have been added Primary Primary Billing Primary Shipping Address Routinely used shipping address if more than one address exists (defaults in sales order)"}, {"u": "customer-record-setup.html#ecommerce-tab", "t": "eCommerce Tab", "p": "SECTION 2:  SALES › Customer Record Setup", "x": "Settings for Internet Ordering based on address. Electronic Ordering Must be checked “Enabled” if choosing to order via website Append Orders Must be checked if choose to combine orders placed on website Compare PO Number Creates new order if PO number doesn’t match previous orders placed MUST be checked if append orders is checked unless otherwise stated"}, {"u": "customer-record-setup.html#backorder-fill-priority-tab", "t": "Backorder Fill Priority Tab", "p": "SECTION 2:  SALES › Customer Record Setup", "x": "Can be used to set customer priority for back order filling. Also, can be done in “Fill Backorder” module."}, {"u": "customer-record-setup.html#custom-fields-tab-user-defined", "t": "Custom Fields Tab (User Defined):", "p": "SECTION 2:  SALES › Customer Record Setup", "x": "Can be used to add additional information pertaining to a customer (i.e. program account numbers, tax exempt numbers, etc.) based on address ID. Provide administrator with desired field name(s) and field number(s) create**.** ( See character requirements below) Fields 1-5 bit (check box) Fields 6-10 varchar (50) Fields 11-15 varchar (200) Fields 16-20 integer Fields 21-30 numeric (12,2) Fields 31-35 datetime When complete with all customer setup information, Save and Close"}, {"u": "customer-contract-pricing-setup.html", "t": "Customer (Contract) Pricing Setup", "p": "SECTION 2:  SALES › Customer (Contract) Pricing Setup", "x": "Allows additional flexibility to set pricing at the customer level in addition to the price level that has been assigned by default in the customer record or the default location price level. Home Screen: FIND Customers – Enter customer name or number and select customer In customer record, select CUSTOMER PRICING tab Note: Customer price rules can be set at any level of the inventory tree down to Sku level. When a branch is selected the rule, set pertains to that branch and all branches and Skus below. All items can also be selected as displayed below with the understanding that ALL items (including non-inventoried items) will have rule applied. Select branch you wish to set rule or go to bottom of inventory tree and search for a specific Sku to apply rule. Select Once you have made your selection for rule, it will display the tree structure as it pertains to your rule in Rule Details as displayed below. Populate: Rule Name: Name using tree branch or Sku rule was created for Class: Cumulative – Chained rule Additive – Works identically to cumulative rule Fixed – Sets fixed price overriding price level rules Margin Ceiling/Margin Floor Round Nearest – Rounds to the nearest value assigned Round Up – Rounds up to the nearest value assigned Base Change Rule – Changes base factor to something other than default setting Matrix – Pricing set based on range of price or range of units Operand: Select %, G% or $ - (GP% selection formula = Base/(1.00-GP%) Value: Enter Value based on above selection (Negative values are allowed) Start Date: Select drop down and choose start date (remove date by unchecking box to left of date) Exp. Date: Select drop down and choose expiration date (remove date by unchecking box to left of date) Active: Validate checked for active status Select: Rule will display under Customer Pricing Rules Select “X” to remove rule Select view prices to view customer pricing in inventory search screen to verify price is as desired Note: Price level rules (created in inventory management) will display based on customer setup at address level. Select: - Allows ALL price rules created within Customer Pricing tab of customer record to be copied to another customer. Select Enter Customer ID or Name to search Check appropriate boxes to search all customers or current location customers Select Search Will display search results based on criteria entered Highlight customer to copy pricing to If multiple search results appears and more than one are desired, highlight first selection, hold CTRL and highlight remaining selections Select OK Information box will appear providing notification copy was successful Notes *:* Presently ALL rules will copy. If there are rules that copy function was not desired, removal will be required on the customer record that they were copied to. Function is limited to do one customer at a time unless search results produce multiple customer results that fall in desired copy to criteria."}, {"u": "customer-deposit.html", "t": "Customer Deposit", "p": "SECTION 2:  SALES › Customer Deposit", "x": "Home Screen: Select then select New Customer Deposit from Start a Task"}, {"u": "customer-deposit.html#create-customer-deposit", "t": "Create Customer Deposit", "p": "SECTION 2:  SALES › Customer Deposit", "x": "Select Customer Search Icon Enter known information in search window (Customer Number, Name, Phone) Select Search Highlight and select OK to desired customer Select Order ID Search Icon if order has already been created Description field required Select desired order if one present on search results screen and select OK Select desired Payment Type If check, enter name and check number (required) If credit card, select card type Enter Payment Amount Select Reset if payment information was needs modified Select Add Payment Displays to the right under added payments Select Save Deposit Populates Deposit ID Select Cancel Deposit if necessary Select Print for receipt to customer Error message will display to verify population of Description field"}, {"u": "customer-deposit.html#reverse-customer-deposit", "t": "Reverse Customer Deposit", "p": "SECTION 2:  SALES › Customer Deposit", "x": "Find and open Customer Deposit FIND: Customer Deposits Select Reverse Confirm you want to reverse, select YES"}, {"u": "received-on-account-roa.html", "t": "Received On Account (ROA)", "p": "SECTION 2:  SALES › Received On Account (ROA)", "x": "Select from application toolbar, Select from dropdown Enter known search criteria Check, Filter for current location if needed Select Search Highlight desired customer Select OK Select Enter Payment information (If check, check number required, if credit card, select card type). Displays payment in payment box Select open invoices for application (If company procedure) If company procedure is to not apply just take payment, DO NOT select invoices for application Select Dialog box will appear if not application, verifying nothing applied, requesting approval to continue Receipt for ROA will display for printing Exit ROA screen"}, {"u": "inventory-management.html", "t": "Inventory Management", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Inventory Management Module is designed to create/manage inventory items, define price levels and rule assignment, maintain cost and base value fields, manage tire fee states, display item detail for TDC (Tire Data Central) and house additional item information as desired. Home Screen: Select Inventory from module toolbar and then"}, {"u": "inventory-management.html#inventory-tree-structure", "t": "Inventory Tree Structure", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Contains 6 levels/branches for tires, parts, retreads, wheels, non-inventoried items, etc. Tree structure maintains commonality for more effective reporting. Designates item that is housed in TDC Designates item that is created locally Items Listed in red are inactive items Manufacturer Defines Manufacturer Name (i.e. Bridgestone-Firestone) Sub-Manufacturer Defines multiple individual brands under the Manufacturer umbrella (i.e. Bridgestone, Firestone, Dayton, Fuzion….) Class Defines tire class (i.e. passenger, light truck, medium truck) Sub-Class Defines type of tire (i.e. All season, All Terrain, Touring….) Category Defines tire line (Ecopia, Destination AT, FR380) Sub-Category Defines additional information of the tire line (i.e. default, Takeoff, Studded….) Use +/- symbols to open the level of the tree structure or enter a specific item number to go directly to item level. Enter item number and select Search SKU Allows the ability to limit the view of the tree structure to specific Sku types (i.e. tires, retreads, catalog parts….)"}, {"u": "inventory-management.html#detail-tab", "t": "Detail Tab", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Tire database of over 105,000 items maintained by TASCO Software providing tire specifications, pictures, comparisons, features and warranty information. This information is also printable and can be emailed from within the inventory search screen."}, {"u": "inventory-management.html#pricing-tab", "t": "Pricing Tab", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Allows you to set and maintain price rules within created price levels based on any level of the inventory tree. Refer to Price Level Maintenance and Price Rule Assignment"}, {"u": "inventory-management.html#site-detail-tab", "t": "Site Detail Tab", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Allows visibility to quantities on hand, committed and ordered along with the ability to view last and average cost. Also allows for population, editing or loading of specific fields designated in white with the selection of . Save when editing is complete. Base Value Fields (20) are editable/loadable fields that can be used for price level base, default pricing, etc. True Cost, Invoice Cost, Calc Cost 1 and Calc Cost 2 are editable/loadable fields that can be used for price level base and/or default cost for invoices, purchase orders, adjustments and receipts Min/Max Reorder Points are editable/loadable fields to set reorder requirements Last Ordered/Shipped dates will automatically update the last date specified item was ordered and/or shipped Preferred Bin(s) used by TireWorks HD Bin Management Module and with 3rd party inventory management software If using TireWorks HD bin management, refer to bin management procedures If using integrated software, this field will need to be flagged for each item that will be managed within the integrated warehouse management software Select + to add Warehouse Management designation and select from list Highlight and select X to remove Warehouse Management designation Tire Fee States – Those states that tire tax will be charged based on tire class"}, {"u": "inventory-management.html#user-defined-tab", "t": "User Defined Tab", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Provides 35 additional informational fields that can be titled and populated for report use only. These consist of a combination of check box fields, various character fields, integer fields, and date fields. Might be used for data such as equivalencies if using integrated routing software."}, {"u": "inventory-management.html#net-specials-tab", "t": "Net Specials Tab", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Provides the ability to set net special pricing for a specified number of units per Sku. This will override any price level and/or customer pricing that is defined at the inventory pricing level or at the customer pricing level. This can also be managed with greater functionality within the selection of the inventor module. Refer to the Net Specials procedures"}, {"u": "inventory-management.html#item-history-tab", "t": "Item History Tab", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Provides an overview of previous 12 months item history of a specified item. Will display by month total sales dollars, sales units, sales average dollars, GP average dollars, receipt dollars, receipt quantity, receipts average dollars and receipts % change dollars."}, {"u": "inventory-management.html#populator-report-tab", "t": "Populator Report Tab", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "DO NOT USE"}, {"u": "inventory-management.html#units-of-measure-tab", "t": "Units of Measure Tab", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Allows functionality to set additional units of measure, assign units of measure at multiple order types or modules. Also provides ability to define dimension settings and weight setting. UPC data would also be housed here. Refer to Unit of Measure Procedures"}, {"u": "inventory-management.html#commission-category-tab", "t": "Commission Category Tab", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Allows item to be assigned to one commission category"}, {"u": "inventory-management.html#asl-tab", "t": "ASL Tab", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Displays locations where selected items have inventory available including transfer price and average cost. Will display a message stating “There are no locations with non-zero quantity for this item” if there aren’t any other locations with quantity available Note: All tabs will allow location to be changed and edited by choosing dropdown and selecting desired location."}, {"u": "inventory-management.html#adding-new-item", "t": "Adding New Item", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "This is done at the Sub-Category level of the inventory tree Highlight desired sub-category (Generally Default) Right Click Select Add Node Move to right and select SKU Will display a local item setup record for population (displayed below) Universal SKU – Populate as it would be created in TDC (Tire Data Central) including three segments of Universal SKU (Simple tire size, three-character mfg. code, and mfg. item number i.e. 2056015FIR123456 ) Item will then automatically move to TDC if the item becomes available and will have ability to view tire detail Manufacturer ID – Enter manufacturer item number Description – Enter description as you wish it to appear in search results and document printing Dealer Base – Enter dealer base if used FET – Enter FET if item is subject to FET (Generally Medium Truck 19.5 and larger) End Date – Automatically defaults to date in future. This is used to designate discontinued product User SKU Code – populate data specific to your business such as Inventory Management Item Number, if different than either universal Sku or manufacturer ID Sku Type – Set appropriate Sku type base on item being created Active – Automatically defaults to active unless check mark is removed Inventoried – Automatically defaults to inventoried unless check mark is removed Stocked – Automatically defaults to stocked unless check box is removed Stocked cannot be set without Inventoried being checked Customer Tax Code – Select appropriate tax code for item being created Program Product Codes – This would be populated if item being added will be used in National Account submission IMPORTANT: Always populate site detail tab when creating a new item. See screenshot above Select Site Detail tab Select Edit Populate required information (cost fields, base value fields, bin assignment, tire fee states, etc.)"}, {"u": "inventory-management.html#screenshotmoving-an-item", "t": "ScreenshotMoving an Item", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "This is done at the Item level of the inventory tree for Local Items only Highlight desired Item Right Click Select Move Item Select appropriate branches based on desired move Select OK"}, {"u": "inventory-management.html#editing-node", "t": "Editing Node", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Allows local item level names to be changed at any of the six levels along with the ability to activate by level. Highlight desired level Right Click Select Edit Node Change name of highlighted level Select OK"}, {"u": "inventory-management.html#activate-inactivate-skus", "t": "Activate/Inactivate Skus", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "Allows one or more items to be activated or inactivated If SINGLE Sku, enter Sku in search box Right click on Active column below search box Select Activate or Inactivate depending or preference Active = 1 Inactive = 0"}, {"u": "inventory-management.html#option-1-multiple-skus", "t": "Option 1 – Multiple Skus", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "If MULTIPLE Skus from same branch level, highlight branch level Returns number of items found Highlight first line item in results Hold shift key and scroll down Highlight last line item Right click on Active column below search box Select Activate or Inactivate depending or preference Active = 1 Inactive = 0"}, {"u": "inventory-management.html#option-2-multiple-skus", "t": "Option 2 – Multiple Skus", "p": "SECTION 3: INVENTORY › Inventory Management", "x": "If MULTIPLE Skus from same branch level, highlight branch level Highlight desired level Right Click Select Edit Node Check active box to right of highest branch to activate Select OK"}, {"u": "price-level-maintenance.html", "t": "Price Level Maintenance", "p": "SECTION 3: INVENTORY › Price Level Maintenance", "x": "Allows flexibility of creating multiple price levels and the ability to assign default price levels to customer records and/or additional company locations. Home Screen: Select Inventory from module toolbar and then"}, {"u": "price-level-maintenance.html#details", "t": "Details", "p": "SECTION 3: INVENTORY › Price Level Maintenance", "x": "Assign Price Level Name Select Price Base from dropdown box – Price rules assigned are calculated from price base. Price Base options included all loadable fields in site detail tab, average cost, last cost, dealer base or any base value fields Parent (default No Parent) – Select from dropdown If parent level is selected, new level will mirror parent level Additional rules can be added Note: This is not a copy function. If rules in parent level change, the rules will change in the newly created level as well."}, {"u": "price-level-maintenance.html#specials", "t": "Specials", "p": "SECTION 3: INVENTORY › Price Level Maintenance", "x": "If price level is created as a special, toggle on “Special” and select start and end date When complete select to save changes or to cancel changes."}, {"u": "price-level-rule-assignment.html", "t": "Price Level Rule Assignment", "p": "SECTION 3: INVENTORY › Price Level Rule Assignment", "x": "Price rules can be set at any level of the inventory tree down to Sku level. When a branch is selected the rule, set pertains to that branch and all branches and Skus below. can also be selected as displayed below with the understanding that ALL items (including non-inventoried items, parts, wheels, etc.) will have rule applied. Home Screen: Select Inventory from module toolbar, then , then Pricing tab Select Price Level rules will be applied from dropdown"}, {"u": "price-level-rule-assignment.html#add-rule-s", "t": "Add Rule(s)", "p": "SECTION 3: INVENTORY › Price Level Rule Assignment", "x": "Highlight branch you wish to set rule or go to bottom of inventory tree and search for a specific Sku to apply rule. Once you have made your selection for rule, select Will display line item in blue with the “from” of the branch you selected Note: Will not display anything above selection. Click in the name field and enter rule name. Be specific (i.e. Firestone LT) or Sku number if setting rule at the Sku level. Tab to Class and select from drop down depending on rule type required Cumulative – Chained rule Additive – Works identically to cumulative rule Fixed – Sets fixed price overriding price level rules Margin Ceiling/Margin Floor Round Nearest – Rounds to the nearest value assigned Round Up – Rounds up to the nearest value assigned Base Change Rule – Changes base factor to something other than default setting Matrix – Pricing set based on range of price or range of units Tab to Operand and select from drop down depending on rule result required %, G% or $ - (GP% selection formula = Base/(1.00-GP%) Tab to Value and select to activate rule prior to populating value Enter rule value Tab to Start Date and select appropriate date from calendar Tab to Expiration Date and select appropriate date from calendar Populate Minimum Cost if Matrix was chosen at class Populate Maximum Cost if Matrix was chosen at class Select to save rule Note: Total column is created automatially based on rule calcuation settings."}, {"u": "price-level-rule-assignment.html#screenshotdelete-rule-s", "t": "ScreenshotDelete Rule(s)", "p": "SECTION 3: INVENTORY › Price Level Rule Assignment", "x": "Highlight rule to delete and select Select to save rule"}, {"u": "price-level-rule-assignment.html#screenshotresort-rule-s", "t": "ScreenshotResort Rule(s)", "p": "SECTION 3: INVENTORY › Price Level Rule Assignment", "x": "Higlight the rule to move and select appropriate directional arrow Select to save rule"}, {"u": "inventory-accounts.html", "t": "Inventory Accounts", "p": "SECTION 3: INVENTORY › Inventory Accounts", "x": "Inventory Accounts Module is used for assignment of GL accounts at any level of the inventory structure. Home Screen: Select Inventory from module toolbar and then"}, {"u": "inventory-accounts.html#assignment-of-gl-accounts", "t": "Assignment of GL Accounts", "p": "SECTION 3: INVENTORY › Inventory Accounts", "x": "Branch assignment will assign GL account for that branch and anything below. Select All Items by highlighting All Items and assign default accounts. This will be default if something is unassigned for any reason Continue selections for GL assignment at any level of the inventory tree IF assigning at Sku level, enter Sku in search box and select Search SKUs Select Save periodically or Save and close when complete"}, {"u": "inventory-receipt.html", "t": "Inventory Receipt", "p": "SECTION 3: INVENTORY › Inventory Receipt", "x": "Used to receive inventory when other than receipt of transfer. Select from application toolbar, Select from dropdown Select Vendor from Dropdown and enter Select from toolbar Option 1: Choose items from multiple POs. Most commonly used. Below instructions are for this option Displays All PO’s for identified vendor Mfg. Sku will be default toggle Option 2: Add all items from a PO Enter Mfg. Sku number on packing list Enter Reference information (required) i.e. bill of lading number Enter quantity received on the correct PO line If less than PO, will display PO line item as partially received and will continue to display in PO list until all items have been received or cancelled If greater than PO Option 1: Enter PO quantity and create new receipt for the difference manually *** ***Option 2: Add additional quantity to PO Note: Option 1 for overage will require pricing to be verified and/or changed. When all items have been added, select Will populate and display on inventory receipt If WMS is NOT used , proceed to Process step below If WMS is used , select and receive in WMS prior to processing inventory receipt Automatically will assign receipt ID, save receipt, and display dialog box reflecting a successful save Status will become (sent to WMS) Once WMS has received product and pushed back receipt information into inventory receipt, open inventory receipt and verify total units received to packing list, and WMS documentation if present Quantity column will be populated from WMS Select Process Choose Process type from dialog box and select Continue Processing Process as Is (default) Cancel un-received items from the original PO Move un-received items to new PO Print inventory Receipt and follow company procedures Receipt will be in Processed status Inventory will be updated in POS"}, {"u": "inventory-receipt.html#audit-history", "t": "Audit History", "p": "SECTION 3: INVENTORY › Inventory Receipt", "x": "Will display all events (adds, changes, deletes) for a specific receipt. Cost changes display changed from and changed to cost."}, {"u": "request-transfer.html", "t": "Request Transfer", "p": "SECTION 3: INVENTORY › Request Transfer", "x": "Used to request transfer from another location. Select from application toolbar. Select from dropdown Select Transfer From location from dropdown Enter Delivery Date (expected date product will be received) Enter Comments if desired Populate Remote Transfer ID (if pertains to company procedure) Populate Sales Order ( if pertains to company procedure) Select Add Items Search products desired and add to shopping cart Quantity available is the quantity available at the requested (sending) location Select add to order Will populate and return to transfer request Average Cost of sending location will default into transfer request (do not modify) Select to process transfer (requested status) Will automatically save and assign the next sequential transfer request number Will display dialog box to verify sending request Will display second dialog box informing request was sent successfully References transfer order number on requested from (sending location) side Print for records or at sending location if desired"}, {"u": "receipt-of-transfer-request.html", "t": "Receipt of Transfer Request", "p": "SECTION 3: INVENTORY › Receipt of Transfer Request", "x": "Used to receive requested transfer. Within Find section of home page, Select If WMS is used, select and receive in WMS prior to receiving product Transfer Request will be (In Transit) status when sending location has fulfilled transfer request Send to WMS and Receive function will only be available in this status Once received in WMS or no WMS is present, verify quantities on transfer request and make any necessary changes to Qty. Received Select Dialog box will display verify receipt of all quantities on grid Reminder to check quantities Transfer Receipt will display for printing if desired Transfer Request will be marked Complete or Partially Received depending on quantities received."}, {"u": "automatic-transfer.html", "t": "Automatic Transfer", "p": "SECTION 3: INVENTORY › Automatic Transfer", "x": "Used to create a transfer in sending location and automatically updates both sending and receiving inventory. Select from application toolbar. Select from dropdown Enter transfer customer (header information will populate) Delivery method will default to Pickup/Will-Call Enter Comments if desired Select Add Items or add via Quick Add Search products desired and add to shopping cart Quantity available is the quantity available at the requested (sending) location Select add to order Will populate Automatic Transfer Average Cost of sending location will default into transfer (do not modify) Continue adding items until all desired product has been added Select Process Automatically generates and processes transfer request for receiving location and processes sending location transfer order (automatically removing/adding product from/to inventory quantity on hand) Invoice from sending location will display for printing"}, {"u": "physical-inventory-count.html", "t": "Physical Inventory Count", "p": "SECTION 3: INVENTORY › Physical Inventory Count", "x": "Provides ability to create a current inventory snapshot, create count book report for manual count or scan inventory, generate variance report and automatically create and process inventory adjustment. Select from home screen. Select Inventory Snapshot from Start a Task"}, {"u": "physical-inventory-count.html#screenshotcreate-inventory-snapshot", "t": "ScreenshotCreate Inventory Snapshot", "p": "SECTION 3: INVENTORY › Physical Inventory Count", "x": "Verify logged into location of desired snapshot Enter desired Snapshot Name (i.e. location number and date) If Partial Inventory (specific Sku types), check box and selected desired Sku types Highlight from Available SKU Types and select Hold CTRL key and select multiples Hold SHIFT and select range Select Done Check Pre-Populate Counts Lists if desired (if manual count not recommended; display QOH ) Select SKU Types Highlight from Available SKU Types and select Hold CTRL key and select multiples Hold SHIFT and select range Select Done Select Automatic display of snapshot detail (Not needed) Select Back to return to Inventory Snapshot screen Once snapshot has been saved additional options will display will discard snapshot will be used to process inventory adjustment"}, {"u": "physical-inventory-count.html#option-1", "t": "OPTION 1", "p": "SECTION 3: INVENTORY › Physical Inventory Count", "x": "Manual Count Sheets Populate filter information/sort orders if desired Is Stocked? - This is not inventoried check box QOH for the Item >0 and <0 – reduces size of list but may create more handwritten items that would have been on list if this checkbox was left unchecked Items sold/ordered within the past XX month(s) Set sort orders by Sku type – Deletes Sort Item From List – Changes Sort Order Check box For All Other Sku Types if not all are listed Select to add Sort Items Use to move Sku types in desired order Select Print Select Print within report display window"}, {"u": "physical-inventory-count.html#option-2", "t": "OPTION 2", "p": "SECTION 3: INVENTORY › Physical Inventory Count", "x": "Mobile Scanning Device Log into Mobile Application Xxxxxxxxxxx Select from home screen. Select Inventory Count List from Start a Task At Create Snapshot, Count List 1 is automatically created If multiple count lists are needed Enter desired Name of count list Enter Description if desired Select Create Countlist Will display in list below Note: This would be needed if multiple employees will be counting or can be used for the variance report research so it can be tracked. Select Green Arrow to right of count list to populate quantities (same order as count report) Select Red Minus to delete count list if needed Enter actual counts or verify scanned counts If blank, will NOT update inventory Note: Only leave blank if not counting. If counting and none found, enter 0 so inventory will be updated accordingly. Save when complete and review prior to submitting if needed Select Submit This will display count list and move Quantities from Counted column to Already Posted column. As additional count sheets are created and submitted “Already Posted” column will update, and that column total will be used on the variance report. IMPORTANT: Additional count sheets should be populated with ONLY what was counted by that team or in the variance review NOT total counts. Note: Use filter to narrow list. Use to enter count for an item that was not on original count list (i.e. 0 QOH item). Use ellipses for advanced search (generally not used). If count sheet was filtered to only include items with quantity, this is a good tool to add all handwritten items that had 0 on hand. Create Variance Report Select from home screen. Select Inventory Snapshot from Start a Task Select Populate filter/sort information (Suggest to use the same as countbook) Is Stocked? - This is not inventoried check box QOH for the Item >0 – reduces size of list but may create more handwritten items that would have been on list if this checkbox was left unchecked Items sold/ordered within the past XX month(s) Set sort criteria Select ellipsis in Edit column Check items for applicable sort columns by and select if descending Highlight and use Up/Down to arrange columns Select Close when complete Toggle “Include items with no variance also” if desired Use to move Sku types in desired order Select Save and Print Review Variance Report Create additional Count Sheets if necessary and submit Reprint Variance Report and repeat process until complete At Inventory Snapshot screen, Select process Inventory adjustment will be created and automatically processed Select Yes Once posted, will display dialog box designating Inventory Adjustment ID Select OK Print adjustment if needed to attach to variance report (Qty and Dollars should match) FIND: Inventory Adjustment and enter ID number"}, {"u": "import-inventory-items.html", "t": "Import Inventory Items", "p": "SECTION 3: INVENTORY › Import Inventory Items", "x": "Import Inventory Items gives users the ability to update data in inventory management site detail fields, base value fields, and user defined fields. select Import Inventory Updates Formatting source document is important to a successful import. Listed below are a few things to verify prior to importing. Name tabs in creating multiples Assign column header names Remove a formatting and/or data that is not needed for import Format"}, {"u": "import-inventory-items.html#import-selection", "t": "Import Selection", "p": "SECTION 3: INVENTORY › Import Inventory Items", "x": "Select ellipsis and browse to desired Excel file. Must be in .xls format (Excel 97-2003) Select desired worksheet (spreadsheet tabs) Select Map Article Code (column headers) Verify need to strip special characters (defaults to checked) Select data will populate in data window"}, {"u": "import-inventory-items.html#data-selection", "t": "Data Selection", "p": "SECTION 3: INVENTORY › Import Inventory Items", "x": "Select desired location information Select desired sub manufacturers Select desired tab Map Inventory Columns Tab – Site Detail Information (See above screenshot) Map Price Bases – Base Value Fields Map UDF Columns – User Defined Fields Select from drop downs the appropriate columns for desired data population Note : Cannot use columns from data source more than once Verify need for Select All Items to be checked (defaults to checked) Verify need to Update Inactive SKU’s (defaults to checked) Verify information in data field is correct Items in source document that are not in inventory management will appear in red Select dialog box will appear to verify the action selection and to alert that action cannot be cancelled Import success dialog box will display Select OK"}, {"u": "shipment-manager-processing-orders-through-invoicing.html", "t": "Shipment Manager (Processing Orders Through Invoicing)", "p": "SECTION 4: WAREHOUSING › Shipment Manager (Processing Orders Through Invoicing)", "x": "From Sales Module: Select Requested Ship Date will default to current date plus a day. Routes are listed in center box based on orders within this screen (Orders in Open Status) Select Routes to process or select ALL Select transfer and/or sales orders Also gives ability to select by order number by un-checking “Select All” and checking each order to process in the process column CHECK ORDERS OPTION: If selected, will go down through all orders and validates all orders are correct. If correct will display a green check mark, if errors will display a red X. To correct those with errors, select the magnifying glass to the left of the order number to open the order and make necessary corrections. Must be run prior to processing orders Select Process Orders – This will mark orders with processing status (un-editable) and populate the picking tab within Shipment Manager. From Warehousing Module: Select"}, {"u": "shipment-manager-processing-orders-through-invoicing.html#picking-tab", "t": "Picking Tab", "p": "SECTION 4: WAREHOUSING › Shipment Manager (Processing Orders Through Invoicing)", "x": "Delivery date will default to next delivery date. Select shipping method desired for picking Sections – Bin management feature – Do not use at this time Routes – Select routes for picking – Can be done on route by route basis or as a whole by checking ALL Select “Generate Pick List” and print – This will print in reverse stop order by route with page break at each route. Will also display order comments. This also moves everything to be picked to the loading tab"}, {"u": "shipment-manager-processing-orders-through-invoicing.html#loading-tab", "t": "Loading Tab", "p": "SECTION 4: WAREHOUSING › Shipment Manager (Processing Orders Through Invoicing)", "x": "Select “Generate Load List and print – This gives you list by route in reverse stop order for loading. This also moves orders to invoicing tab for quantity adjustment, if necessary, and invoice generation Change load quantity if necessary (Can also be done in invoicing tab) Note: If generating pick list multiple times prior to loading, Do NOT generate pick list until you are ready or loading. This will give you’re the correct loading order no matter how many times you are creating the pick list."}, {"u": "shipment-manager-processing-orders-through-invoicing.html#invoicing-tab", "t": "Invoicing Tab", "p": "SECTION 4: WAREHOUSING › Shipment Manager (Processing Orders Through Invoicing)", "x": "Select Ship Via desired for invoicing Verify toggle for unshipped items is toggle to desired practice standards Backorder unshipped items – Will keep items in backorder status on sales order until manually cancelled. Notification of backordered items to sales staff may be necessary. Cancel un-shipped items – Will cancel items that were unable to ship and complete the sales order. Notification to sales staff of cancelled items may be necessary. Change SHIP QTY when necessary prior to printing Use + to open route to view orders included in route Use + to open order to view line items on order Make quantity change in ship qty column Print Delivery Invoices Select routes to print Invoice date equals delivery date (after 5:00p.m. date automatically changes to following day)"}, {"u": "shipment-manager-processing-orders-through-invoicing.html#routes-by-stop-report-route-manifest", "t": "Routes by Stop Report (Route Manifest)", "p": "SECTION 4: WAREHOUSING › Shipment Manager (Processing Orders Through Invoicing)", "x": "This report prints in reverse stop order by route selected. Manifest will go along with the drivers to show what stops are COD, total number of tires by stop, and total number of tires by route. Select Start date End Date will default equal to start date unless otherwise selected Select Route for printing Select view report and select print"}, {"u": "closing-invoices.html", "t": "Closing Invoices", "p": "SECTION 4: WAREHOUSING › Closing Invoices", "x": "Moves Point of Sale sales information to financial software From Warehousing Module: Select"}, {"u": "closing-invoices.html#closing-tab", "t": "Closing Tab", "p": "SECTION 4: WAREHOUSING › Closing Invoices", "x": "Delivery date will default to last invoiced date Verify invoice status is OPEN (default) Displays all invoices to close Select Select all or specific routes to close Verify invoice date Select Process bar will move through and process complete will display in progress box Suggestion *:* At end of each month go through each day and make sure these have all processed."}, {"u": "route-management-stop-assignment.html", "t": "Route Management/Stop Assignment", "p": "SECTION 4: WAREHOUSING › Route Management/Stop Assignment", "x": "Allows standard routing functionality with the ability to assign cutoff times and days of the week delivery specific to the route and/or specific to a stop. Home Screen: Select Warehousing from module toolbar and then"}, {"u": "route-management-stop-assignment.html#create-new-route", "t": "Create New Route", "p": "SECTION 4: WAREHOUSING › Route Management/Stop Assignment", "x": "Select Assign Route Name Select Days of the week delivery Select Previous Day Cutoff (default with be checked) Enter Cutoff Time (in hours ONLY) Enter Departure Time Enter Delivery Fee Sku if applicable (search with ellipses if Sku is unknown)"}, {"u": "route-management-stop-assignment.html#adding-stops", "t": "Adding Stops", "p": "SECTION 4: WAREHOUSING › Route Management/Stop Assignment", "x": "Select Enter as little or as much information as known and select search If multiple shipping addresses, multiple results with display Verify correct address selected Highlight appropriate customer and select OK Will populate on the Route/Stops tab for selected route at the bottom of the stop list Can also be added in the customer record in the Address Tab with appropriate access rights Will display at the top of the stop list Verify days of the week delivery are correct by stop By default, added stop will default to the route default days Once all customers have been added to route, arrange stops by using apropriate At completion of new route, select"}, {"u": "route-management-stop-assignment.html#route-stop-maintenance", "t": "Route/Stop Maintenance", "p": "SECTION 4: WAREHOUSING › Route Management/Stop Assignment", "x": "Delete Route – Highlight appropriate route for deletion, and select Change Route Name – Highlight appropriate route and enter new name Change stop order – Highlight stop to move and use up/down arrows to change stop position Delete stop – Highlight stop to delete and select Change day of week delivery by stop – Highlight stop to change and deselect the days not requested to have delivery Suggestion: When searching for specific customer in long list of stops use CTL + F to enter desired infromation."}, {"u": "bin-management.html", "t": "Bin Management", "p": "SECTION 4: WAREHOUSING › Bin Management", "x": "The Bin Management function allows you to setup Warehouse Sections and Bins. Inventory can be assigned to one or multiple sections/bins for use in Pick Lists, Inventory Receipts, etc. Home Screen: Select Warehousing from module toolbar, and then Bin Management"}, {"u": "bin-management.html#setup-sections", "t": "Setup Sections", "p": "SECTION 4: WAREHOUSING › Bin Management", "x": "Select plus sign at Sections and populate section name and description Repeat until all desired sections have been created Sections can be deleted by highlighting desired section to be deleted and choosing the “x”"}, {"u": "bin-management.html#setup-bins", "t": "Setup Bins", "p": "SECTION 4: WAREHOUSING › Bin Management", "x": "Highlight desired Section Select plus sign at Bins and populate bin name and description Repeat until all desired bins have been created Bins can be deleted by highlighting desired bin to be deleted and choosing the “x”"}, {"u": "bin-management.html#assign-items-to-section-bins", "t": "Assign Items to Section/Bins", "p": "SECTION 4: WAREHOUSING › Bin Management", "x": "Highlight any branch or individual Sku from Inventory Tree tab Drag to the inventory section and drop"}, {"u": "bin-management.html#maintenance-of-new-items", "t": "Maintenance of new items", "p": "SECTION 4: WAREHOUSING › Bin Management", "x": "Unassigned Inventory tab will allow you to see what has not been assigned and the same steps to assign can be used from above. Notes : CTRL button will allow you to select more than one item at a time and SHIFT will allow you to select a range of items (select top item and bottom and it will highlight everything in between) When creating new items via Manage Inventory section and bin can also be associated with item. From Inventory Module select Inventory Management Select Site Detail Tab At Preferred Bin(s) select plus sign Chose desired Sections and Bin from drop downs Select OK Repeat if Sku can be found in multiple bins"}, {"u": "purchase-order-receipt-of-purchase-order.html", "t": "Purchase Order & Receipt of Purchase Order", "p": "SECTION 5: PURCHASING › Purchase Order & Receipt of Purchase Order", "x": "Home Screen: Select then select from start a task"}, {"u": "purchase-order-receipt-of-purchase-order.html#create-purchase-order", "t": "Create Purchase Order", "p": "SECTION 5: PURCHASING › Purchase Order & Receipt of Purchase Order", "x": "Select Vendor from dropdown Vendor information defaults from vendor master Populate Reference (required) Populate delivery date if known Select plus to select from calendar Select X to remove date previously populated Select - Searching same as sales order searching Optional checkbox for Available items only Optional Checkbox for Discontinued items only Discontinued items are set in item master record and display in red Global Lookup: Enter search criteria Universal Sku: simple tire size, three-digit mfg. abbreviation, and mfg. item number (i.e. 2056515GOO402406477) Searchable by all or any combination of Universal Sku Description Filter: Used to narrow search results based on description i.e. line of tire, speed rating, etc.) When description filter is removed goes back to original search results User SKU Code Lookup: Another lookup based on what is populated in User SKU field in item record Optional checkbox to display winter tires only Use Inventory Tree Lookups: Can be used to search by inventory tree nodes Select items to add to order Search results display by largest quantity available Search results display with manufacturer invoice price Enter quantity of desired item and enter. Will move selected item to cart below search screen and return to Global Lookup for next item search Note: ALL search columns are sortable by clicking column header to sort in ascending order. Click again will go back to descending order. Select when all items have been added Items will be populated in purchase order Add comments in desired Select Save Dialog box appears showing successful save Purchase order is assigned next sequential number by location Printable, importable and exportable depending on need Save and close when complete"}, {"u": "purchase-order-receipt-of-purchase-order.html#receipt-of-purchase-order", "t": "Receipt of Purchase Order", "p": "SECTION 5: PURCHASING › Purchase Order & Receipt of Purchase Order", "x": "Reopen original purchase order when product has arrived Select Inventory Receipt will generate within purchase order If WMS is NOT used , proceed to process step below If WMS is used , Select Send to WMS Once WMS has received and transmitted received quantity back to receipt, Select Select to received product Select desired process type (default process as is) and Continue Processing Inventory receipt will display for printing Follow company procedures Inventory status will have status of processed and inventory will be updated in POS"}, {"u": "purchase-order-worksheet.html", "t": "Purchase Order Worksheet", "p": "SECTION 5: PURCHASING › Purchase Order Worksheet", "x": "Used when ordering large quantities from a specific manufacturer Home Screen: Select then select from start a task"}, {"u": "purchase-order-worksheet.html#create-purchase-order", "t": "Create Purchase Order", "p": "SECTION 5: PURCHASING › Purchase Order Worksheet", "x": "Select Vendor from dropdown Vendor information defaults from vendor master Populate Reference (required) Populate delivery date if known Select plus to select from calendar Select X to remove date previously populated Select Worksheet Select Date ranges Select Recommended Method (generally mix max vs. available) Check desired fields (by default all unchecked) Only items with History Retain Search Results Search Inactive Items Check Recommended Quantity Options (by default these are checked) Subtract on Order Qty. Add Backordered Qty. Select Branch of tree and select search Results will display with Qty field populated for those items determined to need replenishment F1 column allows you to select plus and automatically adds to shopping cart F2 displays the item detail information F3 displays 12-month item history Results are searchable by manufacturer or description Add items until complete Select and exit out of worksheet Purchase order will populate Additional items can be added on a one-off basis if needed by using add items Add comments in desired Select Save Dialog box appears showing successful save Purchase order is assigned next sequential number by location Printable, importable and exportable depending on need Save and close when complete"}, {"u": "access-group-setup-access-rights-assignment.html", "t": "Access Group Setup & Access Rights Assignment", "p": "SECTION 6: SYSTEM ADMINISTRATION › Access Group Setup & Access Rights Assignment", "x": "Provides group assignment functionality for individual users with like job duties and responsibilities. From Home Page: Select Administration and from list"}, {"u": "access-group-setup-access-rights-assignment.html#general-tab", "t": "General Tab", "p": "SECTION 6: SYSTEM ADMINISTRATION › Access Group Setup & Access Rights Assignment", "x": "Select Assign Group Name Populate Check Boxes based on View/Edit capabilities required by module"}, {"u": "access-group-setup-access-rights-assignment.html#search-results-tab", "t": "Search Results Tab", "p": "SECTION 6: SYSTEM ADMINISTRATION › Access Group Setup & Access Rights Assignment", "x": "Populates search results with same fields for all members of access group Note: This can also be managed at the user level. Select Search Type from Dropdown Highlight required Available Field desired Select to move to Assigned Fields To remove from Assigned Fields, select and move from Assigned Fields"}, {"u": "access-group-setup-access-rights-assignment.html#copy-existing-access-group", "t": "Copy Existing Access Group", "p": "SECTION 6: SYSTEM ADMINISTRATION › Access Group Setup & Access Rights Assignment", "x": "- Available to copy an existing group Select Copy Group Change name to desired group name at “This Group Already Exists. Please Specify New Group Name” prompt Select OK Auditing Tab – Capability to view audit trails based on selections below. Must be assigned in all locations user has access to. Select desired audit tracking or check Select All box Change location if multiple locations are assigned and repeat process Once all tabs have been populated"}, {"u": "cash-drawer.html", "t": "Cash Drawer", "p": "SECTION 6: SYSTEM ADMINISTRATION › Cash Drawer", "x": "Provides ability to manager petty cash and reconciliation of cash drawer. Also gives an at-a-glance look at sales at any time of the day both by dollars and number of transactions."}, {"u": "cash-drawer.html#cash-drawer-maintenance", "t": "Cash Drawer Maintenance", "p": "SECTION 6: SYSTEM ADMINISTRATION › Cash Drawer", "x": "Select from applicaton toolbar, Select Enter Default Remaining Cash Value in Location Transaction Types tab Select Save"}, {"u": "cash-drawer.html#petty-cash-transactions", "t": "Petty Cash Transactions", "p": "SECTION 6: SYSTEM ADMINISTRATION › Cash Drawer", "x": "Select from applicaton toolbar, Select Select Transaction type from Dropdown list Enter Amount of transaction Verify default Direction or change from dropdown if necessary Enter Transaction Description Verify/Select Print Receipt box Select Save (Select Clear to remove transaction data) Double copy of transaction receipt will display for printing Select Search to display on Transaction List Filterable by drop down selection ranges or customer date range"}, {"u": "cash-drawer.html#cash-reconciliation", "t": "Cash Reconciliation", "p": "SECTION 6: SYSTEM ADMINISTRATION › Cash Drawer", "x": "Select from applicaton toolbar, Select Verify Deposit date (Select from dropdown box to view calendar) Sales – Displays daily sales by payment method Credit Card Detail displays above credit card sales totals Total sales – Sum of all payment types and reflect total sales for selected deposit date Counts – Displays, by default, number of transactions by transaction type Select to view totals in dollars (Invoices will equal total sales) Cash Drawer – Used for reconciliation of cash and bank deposit preparation Beginning Cash on Hand – Daily beginning balance Cash In – Equals amount in Cash Sales Check Receipts – Equals amount in Check Sales Total Cash/Check In – Equals beginning cash on hand, cash in and check receipts ROAs –Total ROA payments collected Misc. Income – Petty cash “In\" transactions Customer Deposits – Amount taken in as customer deposits Paid Outs – Petty cash “Out” transactions Vendor Payments – Not Used BANK DEPOSIT – ONLY EDITABLE FIELD Enter total Amount of bank deposit (Includes customer deposits, ROAs, and petty cash in or out) Ending Cash on Hand – Displays configured daily beginning cash Over/Short – Difference between beginning and ending cash on hand NEW FEATURE : Comment dialog box – Enter text and exit box. Will save with daily cash drawer. Credit Card details Select Save/Reconcile when cash drawer reconciliation is complete Message window will alert you the reconciliation is complete and add check mark to indicate daily transactions are saved and reconciled Select to print report for location or corporate office records if desired Suggestion: Print payout transactions and ROA receipts for the day and attach to cash drawer report Select commit after review of reconciliation Commit confirmation window will appear to alert action is irreversible and prompts to continue No takes you back to reconciled cash drawer Yes prompts reconciliation was committed successfully Note: Depending on company policy, Commit may be done by a different individual or department."}, {"u": "unlocking-objects.html", "t": "Unlocking Objects", "p": "SECTION 6: SYSTEM ADMINISTRATION › Unlocking Objects", "x": "Used to unlock orders, invoices, receipts and purchase orders when warning displays that it is locked by another user. This function can be added to any access group by selecting the appropriate access group and looking for UNLOCK OBJECTS module and check the appropriate boxes for view and/or edit. Generally, however, setting or altering access rights is a function of the Administrator access group. At Home Screen: Select Administration from module tool bar Select Unlock Objects Display will appear with all records that are locked by order type Highlight appropriate object to unlock Can select multiple line items by holding the CTRL key and clicking on each line item you wish to unlock Select Unlock If Multiple selection made, it will ask you if you are sure you want to unlock (total number of line items selected) Select Yes to move forward Select No to go back and reselect line items Select OK"}, {"u": "user-setup-maintenance.html", "t": "User Setup & Maintenance", "p": "SECTION 6: SYSTEM ADMINISTRATION › User Setup & Maintenance", "x": "Users and Salespersons are created via user setup. From Home Screen, Select"}, {"u": "user-setup-maintenance.html#new-user", "t": "New User", "p": "SECTION 6: SYSTEM ADMINISTRATION › User Setup & Maintenance", "x": "Select"}, {"u": "user-setup-maintenance.html#general-tab", "t": "General Tab", "p": "SECTION 6: SYSTEM ADMINISTRATION › User Setup & Maintenance", "x": "Enter UserID (generally first initial last name) Enter Name Enter desired password Enter email address Verify Active status is checked (checked by default when new user is selected) Toggle “Is Salesperson” (checked by default when new user is selected) Select Commission Program user will be associated with Toggle “Use Default Customer on Sales Order” if desired (unchecked by default when new customer is selected). Recommend not checking box Select appropriate locations user will be working from Select the appropriate security profile from drop down box"}, {"u": "user-setup-maintenance.html#pricing-tab", "t": "Pricing Tab", "p": "SECTION 6: SYSTEM ADMINISTRATION › User Setup & Maintenance", "x": "Select approved price level(s) for user from price level list and select to move them to Assigned price levels list If Multiple levels, select first one and hold CTRL key and make the rest of the selections If All levels, select upper most level and hold SHIFT key and select bottom level Toggle “Allow hand pricing” on if desired (Will override access rights assigned to user) Toggle “Enforce minimum profit % and enter percentage Toggle “Enforce maximum markdown % and enter percentage"}, {"u": "user-setup-maintenance.html#auditing-tab", "t": "Auditing Tab", "p": "SECTION 6: SYSTEM ADMINISTRATION › User Setup & Maintenance", "x": "Select ALL in the auditing tab for each location assigned"}, {"u": "user-setup-maintenance.html#salesperson-tab", "t": "Salesperson Tab", "p": "SECTION 6: SYSTEM ADMINISTRATION › User Setup & Maintenance", "x": "Enter salesperson’s names if tied to a specific user/salesperson when complete"}, {"u": "user-setup-maintenance.html#inactivate-user", "t": "Inactivate User", "p": "SECTION 6: SYSTEM ADMINISTRATION › User Setup & Maintenance", "x": "Uncheck active status in general tab (lists all active and inactive users) when complete"}, {"u": "user-setup-maintenance.html#reset-password", "t": "Reset Password", "p": "SECTION 6: SYSTEM ADMINISTRATION › User Setup & Maintenance", "x": "Back out old and enter new – Case sensitive (no second verification required) when complete"}, {"u": "user-setup-maintenance.html#remove-price-levels", "t": "Remove Price Levels", "p": "SECTION 6: SYSTEM ADMINISTRATION › User Setup & Maintenance", "x": "Select approved price level(s) for removal from Assigned Price Level list and select to move them to Price levels list If Multiple levels, select first one and hold CTRL key and make the rest of the selections If All levels, select upper most level and hold SHIFT key and select bottom level when complete"}, {"u": "user-setup-maintenance.html#all-other-changes", "t": "All Other Changes", "p": "SECTION 6: SYSTEM ADMINISTRATION › User Setup & Maintenance", "x": "Follow above procedures"}, {"u": "comment-setup.html", "t": "Comment Setup", "p": "SECTION 6: SYSTEM ADMINISTRATION › Comment Setup", "x": "Designed to create commonly used comments, group comments and assign groups by location for consistency and efficiency. At Home Page: Select from the application task bar then select Comments"}, {"u": "comment-setup.html#adding-comments", "t": "Adding Comments", "p": "SECTION 6: SYSTEM ADMINISTRATION › Comment Setup", "x": "List of all comments needed in Wholesale application Select Comment Code will automatically be highlighted with next sequential number code number Populate Comment Code/short name Populate comment as you would like it to read in comment field of sales order/invoice Checkmark active box Select"}, {"u": "comment-setup.html#adding-comment-groupings", "t": "Adding Comment Groupings", "p": "SECTION 6: SYSTEM ADMINISTRATION › Comment Setup", "x": "Groups comments by type or desired use of comment Select Populate Comment Group Code/group name Populate Comment Group Description to describe code group or user group Select Choose desired comments to be available in Comment Grouping Repeat until all desired comments have been chosen Select (Must have at least one comment assigned to group to save) Comments can be deleted from groupings by highlighting line to delete and selecting"}, {"u": "comment-setup.html#assigning-location-comments", "t": "Assigning Location Comments", "p": "SECTION 6: SYSTEM ADMINISTRATION › Comment Setup", "x": "Allows the ability to limit, by location, the comments that will not be utilized. Highlight location desired to assign Comment Groupings Select appropriate grouping from dropdown list (ONLY one per location) Select"}, {"u": "comment-maintenance.html#remove-comments", "t": "Remove Comments", "p": "SECTION 6: SYSTEM ADMINISTRATION › Comment Maintenance", "x": "Highlight desired comment and uncheck active box Automatically removes from Comment Groupings Select Select to view list of inactive comments Checking active box will reactivate and display on back on list Will automatically add back to Comment Groupings"}, {"u": "comment-maintenance.html#delete-comments-from-comment-grouping", "t": "Delete comments from Comment Grouping", "p": "SECTION 6: SYSTEM ADMINISTRATION › Comment Maintenance", "x": "Highlight line to delete in comments field and selecting Select *** Note:* Cannot delete or inactivate a Comment Grouping ."}, {"u": "comment-maintenance.html#changing-location-grouping-assigned-to-a-location", "t": "Changing Location Grouping assigned to a location", "p": "SECTION 6: SYSTEM ADMINISTRATION › Comment Maintenance", "x": "Select desired grouping from dropdown of location to be changed"}, {"u": "comment-maintenance.html#removing-grouping-from-location", "t": "Removing Grouping from location", "p": "SECTION 6: SYSTEM ADMINISTRATION › Comment Maintenance", "x": "select next to dropdown of location desiring to clear"}];